import React from "react";
import { Link } from "react-router-dom";

const Header = () => {
  return (
    <div><header className="bg-[#0B0F1A] text-[#E0E6F0] p-5 flex justify-between items-center">
      <h2 className="text-sky-400 font-semibold text-xl">MedVision AI Lab</h2>

      <nav className="flex gap-10 text-base">
        <Link
          to="/Upload"
          className="hover:text-sky-400 transition-colors duration-300 cursor-pointer"
        >
          Uploads
        </Link>

        <Link
          to="/Analysis"
          className="hover:text-sky-400 transition-colors duration-300"
        >
          Analysis
        </Link>

        <Link
          to="/Consult"
          className="hover:text-sky-400 transition-colors duration-300"
        >
          Consult
        </Link>
      </nav>
    </header></div>

  );
};

export default Header;
